const chapters=[
 {n:'01',title:'AI Literacy',meta:'40 MCQs · foundations to responsible AI',file:'01-ai-literacy.md',desc:'AI foundations, prompting, advanced systems, and evaluation.'},
 {n:'02',title:'Technical Assessment',meta:'48 MCQs · logic, DSA, engineering',file:'02-technical-assessment.md',desc:'Sharpen programming logic, algorithms, and software fundamentals.'},
 {n:'03',title:'Debugging Assessment',meta:'8 worked problems · C/C++/Java',file:'03-debugging-assessment.md',desc:'Use a disciplined Review → Identify → Fix → Validate loop.'},
 {n:'04',title:'AI-Assisted Coding',meta:'6 scenarios · prompt & review',file:'04-ai-assisted-coding.md',desc:'Practise guiding AI, then checking every decision yourself.'},
 {n:'05',title:'HR & Behavioral',meta:'30 questions · bonus chapter',file:'05-hr-behavioral-bonus.md',desc:'Build concise, honest stories for human conversations.'},
 {n:'06',title:'Live Coding',meta:'2 MERN/React scenarios · bonus',file:'06-live-coding-scenarios.md',desc:'Read existing code, diagnose carefully, and narrate your logic.'}
];
const questions=[
 {topic:'AI LITERACY',q:'What is a foundation model?',a:['A small model for one narrow task','A broad model adapted to many downstream tasks','A rule-based expert system','A database indexing technique'],correct:1,why:'Foundation models learn broad patterns first, then can be adapted for specific tasks.'},
 {topic:'TECHNICAL ASSESSMENT',q:'What does x % y return in most programming languages?',a:['The decimal quotient','The remainder after division','The larger number','The rounded quotient'],correct:1,why:'The modulo operator returns the remainder left after integer division.'},
 {topic:'DEBUGGING',q:'Before editing a bug, what is the strongest first move?',a:['Rewrite the function from scratch','Read the full problem and entire code path','Search online for a solution','Change the first suspicious line'],correct:1,why:'A complete read helps you understand intent and avoid fixing the symptom instead of the cause.'},
 {topic:'AI-ASSISTED CODING',q:'What should you ask for before requesting code?',a:['The final answer immediately','Two possible approaches and their complexity','A longer prompt with no details','Only test cases'],correct:1,why:'Comparing approaches first demonstrates problem-solving and helps you choose deliberately.'},
 {topic:'RESPONSIBLE AI',q:'Which is a key limitation of current LLMs?',a:['They cannot produce text','They may generate plausible but false information','They only work with images','They are rule-based systems'],correct:1,why:'LLMs can hallucinate, so facts and code should always be checked.'},
 {topic:'INTERVIEW PRACTICE',q:'A strong fresher answer to “Tell me about yourself” usually starts with:',a:['A full resume recital','Education, relevant skills/projects, then the role you want','Salary expectations','A list of every hobby'],correct:1,why:'A short, connected story makes your background relevant and easy to follow.'}
];
const grid=document.querySelector('#roadmapGrid'), resources=document.querySelector('#resourceList');
const done=JSON.parse(localStorage.getItem('cphq-done')||'[]');
function renderRoadmap(){grid.innerHTML=chapters.map(c=>`<article class="module ${done.includes(c.n)?'complete':''}"><div class="module-top"><span>MODULE ${c.n}</span><span class="check">${done.includes(c.n)?'✓':''}</span></div><h3>${c.title}</h3><p>${c.desc}</p><button data-module="${c.n}">${done.includes(c.n)?'Completed ✓':'Mark complete +'} </button></article>`).join('');document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{const n=b.dataset.module;const i=done.indexOf(n);i>=0?done.splice(i,1):done.push(n);localStorage.setItem('cphq-done',JSON.stringify(done));renderRoadmap()})}
resources.innerHTML=chapters.map(c=>`<a class="resource" href="sections/${c.file}"><span class="resource-num">${c.n}</span><span><h3>${c.title}</h3><p>${c.meta}</p></span><span>↗</span></a>`).join('');renderRoadmap();
document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>document.querySelector('#'+b.dataset.jump).scrollIntoView());document.querySelector('#resetProgress').onclick=()=>{localStorage.removeItem('cphq-done');done.length=0;renderRoadmap()};
let index=0,answered=false;const el={count:document.querySelector('#questionCount'),topic:document.querySelector('#quizTopic'),text:document.querySelector('#questionText'),answers:document.querySelector('#answers'),feedback:document.querySelector('#quizFeedback'),next:document.querySelector('#nextQuestion'),bar:document.querySelector('#progressBar')};
function renderQuestion(){const x=questions[index];answered=false;el.count.textContent=`QUESTION ${index+1} OF ${questions.length}`;el.topic.textContent=x.topic;el.text.textContent=x.q;el.feedback.textContent='Choose an answer to continue.';el.next.disabled=true;el.next.textContent=index===questions.length-1?'Finish ✓':'Next →';el.bar.style.width=`${(index+1)/questions.length*100}%`;el.answers.innerHTML=x.a.map((a,i)=>`<button class="answer" data-a="${i}"><b>${String.fromCharCode(65+i)}.</b> ${a}</button>`).join('');el.answers.querySelectorAll('.answer').forEach(b=>b.onclick=()=>answer(+b.dataset.a))}
function answer(n){if(answered)return;answered=true;const x=questions[index],buttons=el.answers.querySelectorAll('.answer');buttons[x.correct].classList.add('correct');if(n!==x.correct)buttons[n].classList.add('wrong');else buttons[n].classList.add('selected');el.feedback.textContent=(n===x.correct?'Correct — ':'Keep going — ')+x.why;el.next.disabled=false}
el.next.onclick=()=>{if(index<questions.length-1){index++;renderQuestion()}else{index=0;renderQuestion();el.feedback.textContent='Drill complete! Start again to reinforce the concepts.'}};renderQuestion();
let left=720;setInterval(()=>{left=Math.max(0,left-1);document.querySelector('#timer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`},1000);
